+use std::io::{Read, Write};
+use std::net::{TcpListener, TcpStream};
+use ping_pong_api::{handle, Method};
+
+fn main() -> std::io::Result<()> {
+    let listener = TcpListener::bind(("0.0.0.0", 3000))?;
+    let mut count = 0;
+    println!("Ping-pong API listening on http://0.0.0.0:3000");
+    for stream in listener.incoming() {
+        if let Ok(mut stream) = stream {
+            count = respond(&mut stream, count)?;
+        }
+    }
+    Ok(())
+}
+
+fn respond(stream: &mut TcpStream, count: u64) -> std::io::Result<u64> {
+    let mut request = [0; 1024];
+    let size = stream.read(&mut request)?;
+    let first_line = String::from_utf8_lossy(&request[..size]).lines().next().unwrap_or("");
+    let mut parts = first_line.split_whitespace();
+    let method = if parts.next() == Some("GET") { Method::Get } else { Method::Other };
+    let path = parts.next().unwrap_or("/").split('?').next().unwrap_or("/");
+    let (response, next_count) = handle(path, method, count);
+    let body = match response.status { 200 => format!(r#"{{"message":"pong","count":{}}}"#, response.count), 404 => r#"{"error":"Not Found"}"#.into(), _ => r#"{"error":"Method Not Allowed"}"#.into() };
+    let allow = if response.status == 405 { "Allow: GET\r\n" } else { "" };
+    write!(stream, "HTTP/1.1 {}\r\nContent-Type: application/json; charset=utf-8\r\nContent-Length: {}\r\n{}\r\n{}", response.status, body.len(), allow, body)?;
+    Ok(next_count)
+}

